CREATE TABLE nb_iam_sessions (id_hash CHAR(64) PRIMARY KEY, token_cipher TEXT NOT NULL, csrf_token VARCHAR(64) NOT NULL, expires_at DATETIME(3) NOT NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), INDEX idx_session_expiry(expires_at));
CREATE TABLE nb_iam_login_states (state_hash CHAR(64) PRIMARY KEY, verifier_cipher TEXT NOT NULL, nonce VARCHAR(64) NOT NULL, expires_at DATETIME(3) NOT NULL);
CREATE TABLE nb_image_tasks (id VARCHAR(64) PRIMARY KEY, tenant_id BIGINT NOT NULL, owner_user_id BIGINT NOT NULL, provider VARCHAR(30) NOT NULL, upstream_id VARCHAR(255), status VARCHAR(30) NOT NULL DEFAULT 'REGISTERING', prompt TEXT NOT NULL, model VARCHAR(100) NOT NULL DEFAULT '', settings JSON, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), INDEX idx_task_tenant_owner(tenant_id,owner_user_id,created_at), UNIQUE KEY uk_provider_upstream(tenant_id,provider,upstream_id));
CREATE TABLE nb_image_assets (id VARCHAR(64) PRIMARY KEY, task_id VARCHAR(64) NOT NULL, tenant_id BIGINT NOT NULL, owner_user_id BIGINT NOT NULL, source_cipher MEDIUMTEXT NOT NULL, source_hash CHAR(64) NOT NULL, mime_type VARCHAR(100) NOT NULL DEFAULT 'image/png', status VARCHAR(30) NOT NULL DEFAULT 'REGISTERING', created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), INDEX idx_asset_tenant_owner(tenant_id,owner_user_id,created_at), UNIQUE KEY uk_task_source(task_id,source_hash));
CREATE TABLE nb_iam_outbox (id BIGINT PRIMARY KEY AUTO_INCREMENT, tenant_id BIGINT NOT NULL, resource_type VARCHAR(40) NOT NULL, resource_key VARCHAR(64) NOT NULL, payload JSON NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'PENDING', attempts INT NOT NULL DEFAULT 0, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE KEY uk_outbox_resource(tenant_id,resource_type,resource_key));
